package view;

import bus.device.MaintenanceBUS;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import model.auth.AuthenticatedSession;
import model.device.MaintenanceModels.*;
import view.component.UIStyle;

final class MaintenancePanel extends JPanel {
    private final AuthenticatedSession session; private final MaintenanceBUS bus=new MaintenanceBUS(); private final boolean schedule;
    private final JTextField search=new JTextField(); private final DefaultTableModel model=new DefaultTableModel(); private final JTable table=new JTable(model); private final JButton edit=new JButton("Chỉnh sửa"); private final JButton delete=new JButton("Xóa");
    MaintenancePanel(AuthenticatedSession s,boolean schedule){session=s;this.schedule=schedule;setLayout(new BorderLayout(0,12));setBackground(MainFrame.PAGE);setBorder(BorderFactory.createEmptyBorder(18,18,18,18));add(header(),BorderLayout.NORTH);add(body(),BorderLayout.CENTER);load();}
    private JPanel header(){JPanel p=new JPanel(new BorderLayout());p.setOpaque(false);JLabel t=new JLabel(schedule?"Lịch bảo dưỡng thiết bị":"Phiếu sửa chữa thiết bị");t.setFont(new java.awt.Font("Segoe UI",java.awt.Font.BOLD,20));t.setForeground(MainFrame.TEXT);JButton add=new JButton("+ Thêm mới");UIStyle.primaryButton(add);add.addActionListener(e->open(null));p.add(t,BorderLayout.WEST);p.add(add,BorderLayout.EAST);return p;}
    private JPanel body(){JPanel p=new JPanel(new BorderLayout(0,10));p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(MainFrame.BORDER),BorderFactory.createEmptyBorder(12,12,12,12)));search.setPreferredSize(new Dimension(360,34));UIStyle.field(search);search.putClientProperty("JTextField.placeholderText","Tìm mã thiết bị, tên thiết bị...");search.addActionListener(e->load());JButton refresh=new JButton("Làm mới");UIStyle.secondaryButton(refresh);refresh.addActionListener(e->load());UIStyle.secondaryButton(edit);UIStyle.dangerButton(delete);edit.setEnabled(false);delete.setEnabled(false);edit.addActionListener(e->open(selected()));delete.addActionListener(e->remove());table.getSelectionModel().addListSelectionListener(e->{boolean on=selected()!=null;edit.setEnabled(on);delete.setEnabled(on);});JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,6,0));actions.setOpaque(false);actions.add(edit);actions.add(delete);actions.add(refresh);JPanel top=new JPanel(new BorderLayout(8,0));top.setOpaque(false);top.add(search,BorderLayout.CENTER);top.add(actions,BorderLayout.EAST);UIStyle.table(table);table.setAutoCreateRowSorter(true);p.add(top,BorderLayout.NORTH);p.add(new JScrollPane(table),BorderLayout.CENTER);return p;}
    private void load(){new SwingWorker<List<?>,Void>(){protected List<?> doInBackground(){return schedule?bus.schedules(session,search.getText()):bus.repairs(session,search.getText());}protected void done(){try{List<?> rows=get();if(schedule){model.setDataVector(new Object[0][7],new Object[]{"Mã","Thiết bị","Ngày dự kiến","Ngày thực hiện","Nội dung","Trạng thái","__row"});for(Object o:rows){Schedule x=(Schedule)o;model.addRow(new Object[]{x.id(),x.deviceId()+" - "+x.deviceName(),x.expectedDate(),x.completedDate(),x.content(),x.status(),x});}}else{model.setDataVector(new Object[0][7],new Object[]{"Mã","Thiết bị","Ngày báo","Mô tả sự cố","Ngày sửa","Trạng thái","__row"});for(Object o:rows){Repair x=(Repair)o;model.addRow(new Object[]{x.id(),x.deviceId()+" - "+x.deviceName(),x.reportedDate(),x.description(),x.repairedDate(),x.status(),x});}table.getColumnModel().getColumn(6).setMinWidth(0);table.getColumnModel().getColumn(6).setMaxWidth(0);table.getColumnModel().getColumn(6).setWidth(0);}}catch(Exception e){UIStyle.showError(thisPanel(),message(e));}}}.execute();}
    private void open(Object old){try{JTextField device=new JTextField(old==null?"":schedule?((Schedule)old).deviceId():((Repair)old).deviceId());JTextField date=new JTextField(old==null?LocalDate.now().toString():schedule?String.valueOf(((Schedule)old).expectedDate()):String.valueOf(((Repair)old).repairedDate()));JTextField content=new JTextField(old==null?"":schedule?safe(((Schedule)old).content()):safe(((Repair)old).description()));JTextField vendor=new JTextField(old==null?"":schedule?safe(((Schedule)old).vendor()):safe(((Repair)old).vendor()));JTextField cost=new JTextField(old==null?"":String.valueOf(schedule?((Schedule)old).cost():((Repair)old).cost()));String[] states=schedule?new String[]{"LenLich","DaThucHien","QuaHan","Huy"}:new String[]{"MoiBao","DangXuLy","DaSua","KhongTheSua","Huy"};JComboBox<String> state=new JComboBox<>(states);if(old!=null)state.setSelectedItem(schedule?((Schedule)old).status():((Repair)old).status());JPanel f=new JPanel(new GridLayout(0,2,8,8));f.add(new JLabel("Mã thiết bị"));f.add(device);f.add(new JLabel(schedule?"Ngày dự kiến":"Ngày sửa (yyyy-MM-dd)"));f.add(date);f.add(new JLabel(schedule?"Nội dung":"Mô tả sự cố"));f.add(content);f.add(new JLabel("Đơn vị thực hiện"));f.add(vendor);f.add(new JLabel("Chi phí"));f.add(cost);f.add(new JLabel("Trạng thái"));f.add(state);int ok=JOptionPane.showConfirmDialog(this,f,schedule?"Lịch bảo dưỡng":"Phiếu sửa chữa",JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE);if(ok!=JOptionPane.OK_OPTION)return;Long id=old==null?null:(schedule?((Schedule)old).id():((Repair)old).id());BigDecimal amount=cost.getText().isBlank()?null:new BigDecimal(cost.getText());if(schedule)bus.save(session,new ScheduleDraft(id,device.getText(),LocalDate.parse(date.getText()),null,content.getText(),vendor.getText(),null,amount,(String)state.getSelectedItem()));else bus.save(session,new RepairDraft(id,device.getText(),content.getText(),LocalDate.parse(date.getText()),vendor.getText(),amount,(String)state.getSelectedItem(),null,null));load();}catch(Exception e){UIStyle.showError(this,message(e));}}
    private Object selected(){int r=table.getSelectedRow();return r<0?null:model.getValueAt(table.convertRowIndexToModel(r),6);}
    private void remove(){Object old=selected();if(old==null||JOptionPane.showConfirmDialog(this,"Bạn có chắc muốn xóa bản ghi này?","Xác nhận",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{long id=schedule?((Schedule)old).id():((Repair)old).id();bus.delete(session,id,schedule);load();}catch(Exception e){UIStyle.showError(this,message(e));}}
    private JPanel thisPanel(){return this;}private static String safe(String x){return x==null?"":x;}private static String message(Exception e){Throwable c=e.getCause()==null?e:e.getCause();return c.getMessage()==null?"Không thể thực hiện thao tác.":c.getMessage();}
}
